pub fn default_agent_binaries_for(provider: &str) -> Vec<String> {
    let s = |v: &[&str]| v.iter().map(|x| (*x).to_string()).collect();
    match provider {
        "anthropic" => s(&["claude"]),
        "openai" => s(&["codex"]),
        "google" => s(&["gemini"]),
        "mistral" => s(&["mistral"]),
        "deepseek" => s(&["deepseek"]),
        "cohere" => s(&["cohere"]),
        "xai" => s(&["grok", "xai"]),
        "microsoft" => s(&["copilot"]),
        _ => Vec::new(),
    }
}

